{"code": "testing_dir = pathlib.Path("data_small/handwritten-marathi-character-dataset-of-4-people/Testing_Data")

if testing_dir.exists() and testing_dir.is_dir():
    classes = sorted([d.name for d in testing_dir.iterdir() if d.is_dir()])
    print(f"Total classes in Testing_Data: {len(classes)}")
    print(f"First 10 classes: {classes[:10]}")

    total_files = 0
    for c in classes:
        files = list(testing_dir.glob(f"{c}/*.jpg"))
        total_files += len(files)
        if c in classes[:5]:
            print(f"  {c}: {len(files)} files")
    print(f"\nTotal files: {total_files}")"}

