testing_dir = pathlib.Path("data_small/handwritten-marathi-character-dataset-of-4-people/Testing_Data")

for class_dir in sorted(testing_dir.iterdir())[:3]:
    if class_dir.is_dir():
        files = list(class_dir.glob('*.jpg'))
        print(f"\nClass {class_dir.name}:")
        for f in files:
            with open(f, 'rb') as file:
                header = file.read(8)
                print(f"  {f.name}: header = {header[:4].hex()}")"}

